-- Esquema inicial PostgreSQL para o protótipo Atleta em Foco.

CREATE TABLE "Athlete" (
    "AthleteId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "FullName" varchar(150) NOT NULL,
    "IsActive" boolean NOT NULL DEFAULT TRUE,
    "CreatedAt" timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "AppUser" (
    "AppUserId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Username" varchar(254) NOT NULL UNIQUE,
    "PasswordHash" varchar(500) NOT NULL,
    "Role" varchar(20) NOT NULL,
    "AthleteId" integer NULL REFERENCES "Athlete" ("AthleteId"),
    "IsActive" boolean NOT NULL DEFAULT TRUE,
    "CreatedAt" timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "CK_AppUser_Role" CHECK ("Role" IN ('Athlete', 'Commission', 'Admin')),
    CONSTRAINT "CK_AppUser_AthleteRole" CHECK (
        ("Role" = 'Athlete' AND "AthleteId" IS NOT NULL)
        OR ("Role" IN ('Commission', 'Admin') AND "AthleteId" IS NULL)
    )
);
CREATE UNIQUE INDEX "UX_AppUser_OneAccountPerAthlete"
    ON "AppUser" ("AthleteId") WHERE "AthleteId" IS NOT NULL;
CREATE UNIQUE INDEX "UX_AppUser_OneCommissionAccount"
    ON "AppUser" ("Role") WHERE "Role" = 'Commission';

CREATE TABLE "TrainingSession" (
    "TrainingSessionId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "StartsAt" timestamp(0) NOT NULL,
    "SessionType" varchar(20) NOT NULL,
    "Description" varchar(250) NULL,
    "CreatedAt" timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "CK_TrainingSession_Type" CHECK ("SessionType" IN ('Training', 'Match'))
);

CREATE TABLE "Evaluation" (
    "EvaluationId" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "AthleteId" integer NOT NULL REFERENCES "Athlete" ("AthleteId"),
    "SubmittedByUserId" integer NOT NULL REFERENCES "AppUser" ("AppUserId"),
    "TrainingSessionId" integer NULL REFERENCES "TrainingSession" ("TrainingSessionId"),
    "EvaluationType" varchar(10) NOT NULL,
    "SubmittedAt" timestamp(0) with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "CK_Evaluation_Type" CHECK ("EvaluationType" IN ('Pre', 'Post'))
);
CREATE INDEX "IX_Evaluation_Athlete_SubmittedAt"
    ON "Evaluation" ("AthleteId", "SubmittedAt" DESC);
-- Em PostgreSQL, valores NULL já não colidem em um índice UNIQUE.
CREATE UNIQUE INDEX "UX_Evaluation_Athlete_Session_Type"
    ON "Evaluation" ("AthleteId", "TrainingSessionId", "EvaluationType");

CREATE TABLE "PreTrainingResponse" (
    "EvaluationId" bigint PRIMARY KEY REFERENCES "Evaluation" ("EvaluationId"),
    "Recovery" smallint NOT NULL CHECK ("Recovery" BETWEEN 1 AND 10),
    "SleepHours" numeric(4,2) NOT NULL CHECK ("SleepHours" BETWEEN 0 AND 24),
    "SleepQuality" smallint NOT NULL CHECK ("SleepQuality" BETWEEN 1 AND 7),
    "Stress" smallint NOT NULL CHECK ("Stress" BETWEEN 1 AND 7),
    "MuscleFatigue" smallint NOT NULL CHECK ("MuscleFatigue" BETWEEN 1 AND 7),
    "Hydration" smallint NOT NULL CHECK ("Hydration" BETWEEN 1 AND 8),
    "NoPain" boolean NOT NULL
);

CREATE TABLE "PainRegion" (
    "EvaluationId" bigint NOT NULL REFERENCES "PreTrainingResponse" ("EvaluationId"),
    "RegionCode" varchar(30) NOT NULL,
    CONSTRAINT "PK_PainRegion" PRIMARY KEY ("EvaluationId", "RegionCode"),
    CONSTRAINT "CK_PainRegion_RegionCode" CHECK ("RegionCode" IN (
        'head', 'neck', 'shoulderL', 'shoulderR', 'armL', 'armR',
        'elbowL', 'elbowR', 'wristL', 'wristR', 'handL', 'handR',
        'chest', 'back', 'abdomen', 'hipL', 'hipR', 'thighL', 'thighR',
        'kneeL', 'kneeR', 'calfL', 'calfR', 'ankleL', 'ankleR', 'footL', 'footR'
    ))
);

CREATE TABLE "PostTrainingResponse" (
    "EvaluationId" bigint PRIMARY KEY REFERENCES "Evaluation" ("EvaluationId"),
    "Effort" smallint NOT NULL CHECK ("Effort" BETWEEN 1 AND 10),
    "DurationMinutes" smallint NOT NULL CHECK ("DurationMinutes" BETWEEN 1 AND 600)
);

-- Necessário para que a configuração inicial pela interface possa criar os acessos.
